CardSets.register({"id":"candy","name":"Candy","code":"CANDY","description":"420 cards of pure sugar — chocolate bars, gummies, sours, gum and the gone-but-not-forgotten classics, from Reese's Cups and the surprise egg to Pop Rocks and candy corn. Sweet tooth required.","theme":{"primary":"#e5488c","secondary":"#7b3fbf","artBackground":"#fff6ec","artFit":"contain"},"pack":{"name":"Candy Pack","emblem":"🍬","skin":"candy"},"cards":[{"name":"Reese's Peanut Butter Cups","rarity":"chase","id":"reeses-peanut-butter-cups","subtitle":"Chocolate","details":"Created in 1928 by former Hershey employee H.B. Reese; a peanut butter filling in a ridged milk chocolate cup.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2020-04-30_02_10_40_Two_Reese%27s_Peanut_Butter_Cups_with_the_inner_paper_cup_intact_in_the_Franklin_Farm_section_of_Oak_Hill%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"M&M's Milk Chocolate","rarity":"chase","id":"m-ms-milk-chocolate","subtitle":"Chocolate","details":"Launched by Mars in 1941; milk chocolate lentils in a colorful candy shell that melts in your mouth, not your hand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plain-M%26Ms-Pile.jpg?width=1024"},{"name":"Snickers","rarity":"chase","id":"snickers","subtitle":"Chocolate","details":"Introduced by Mars in 1930 and named for a family horse; peanuts, caramel and nougat under milk chocolate.","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/Snickers-broken.png"},{"name":"Hershey's Milk Chocolate Bar","rarity":"chase","id":"hersheys-milk-chocolate-bar","subtitle":"Chocolate","details":"Hershey's original bar, launched in 1900; plain, sweet milk chocolate that set the American chocolate standard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hershey-bar-open.JPG?width=1024"},{"name":"Kit Kat","rarity":"chase","id":"kit-kat","subtitle":"Chocolate","details":"Created by Rowntree in Britain in 1935; crisp wafers fingered in milk chocolate, made to snap and share.","image":"https://upload.wikimedia.org/wikipedia/commons/d/dd/KitKat.jpg"},{"name":"Twix","rarity":"legendary","id":"twix","subtitle":"Chocolate","details":"A Mars bar of two biscuit fingers topped with caramel and coated in milk chocolate, built for crunch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Twix-broken.jpg?width=1024"},{"name":"M&M's Peanut","rarity":"legendary","id":"m-ms-peanut","subtitle":"Chocolate","details":"Debuted in 1954; a whole roasted peanut inside each colorful shell, the first M&M's variety beyond plain.","image":"assets/sets/candy/images/m-ms-peanut.webp"},{"name":"Hershey's Kisses Milk Chocolate","rarity":"legendary","id":"hersheys-kisses-milk-chocolate","subtitle":"Chocolate","details":"Introduced by Hershey in 1907; flat-bottomed teardrops of milk chocolate with a plume-like paper strip.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c5/Hershey%27s_KISSES_Chocolate_Flavors_Written_on_Paper_Plume.jpg"},{"name":"Reese's Pieces","rarity":"legendary","id":"reeses-pieces","subtitle":"Chocolate","details":"Candy-coated peanut butter pieces launched in 1978; shot to fame as the alien's treat in the 1982 film E.T.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reese%27s_Pieces%2C_Canada%2C_2026-02-27_03.jpg?width=1024"},{"name":"Butterfinger","rarity":"legendary","id":"butterfinger","subtitle":"Chocolate","details":"Created in Chicago in 1923; a crispety, crunchety peanut-butter core covered in chocolatey coating.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2020-03-15_01_58_20_A_broken_Butterfinger_bar_from_a_Butterfinger_2_Piece_with_the_wrapper_removed_the_Franklin_Farm_section_of_Oak_Hill%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"Milky Way","rarity":"legendary","id":"milky-way","subtitle":"Chocolate","details":"Frank Mars's 1923 bar of fluffy nougat and caramel in milk chocolate, inspired by a chocolate malt shake.","image":"https://images.openfoodfacts.org/images/products/500/015/956/2676/front_fr.3.400.jpg"},{"name":"3 Musketeers","rarity":"legendary","id":"3-musketeers","subtitle":"Chocolate","details":"A Mars bar from 1932; originally three vanilla, chocolate and strawberry nougat sections in one wrapper.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2021-05-19_12_06_37_A_3_Musketeers_bar_in_the_Franklin_Farm_section_of_Oak_Hill%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"Almond Joy","rarity":"legendary","id":"almond-joy","subtitle":"Chocolate","details":"Launched in 1946; moist coconut and a whole almond under milk chocolate, sold as the twin of Mounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Almond-joy-broken.jpg?width=1024"},{"name":"Mounds","rarity":"epic","id":"mounds","subtitle":"Chocolate","details":"The almond-free twin: sweet coconut under dark chocolate, for purists who want coconut front and center.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Mounds-Broken.jpg?width=1024"},{"name":"Hershey's Cookies 'n' Creme Bar","rarity":"epic","id":"hersheys-cookies-n-creme-bar","subtitle":"Chocolate","details":"Hershey's white creme bar studded with chocolate cookie bits, a cookies-and-cream twist on the classic bar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Hersheys-CookiesCreme-Broken.jpg?width=1024"},{"name":"Crunch","rarity":"legendary","id":"crunch","subtitle":"Chocolate","details":"A Nestle bar from 1938; milk chocolate laced with crisped rice for a light, crackly bite in every square.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Nestl%C3%A9_Crunch.jpg"},{"name":"100 Grand","rarity":"legendary","id":"100-grand","subtitle":"Chocolate","details":"Launched in 1964 as the $100,000 Bar; caramel, crispy rice and peanuts named for a game-show-sized prize.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-100Grand-Broken.jpg?width=1024"},{"name":"Baby Ruth","rarity":"epic","id":"baby-ruth","subtitle":"Chocolate","details":"A 1921 Chicago bar of peanuts and caramel in chocolate; its name honors baseball-era America, not a recipe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baby-Ruth-Split.jpg?width=1024"},{"name":"Whoppers","rarity":"legendary","id":"whoppers","subtitle":"Chocolate","details":"Malted milk balls in a chocolatey coating; crunchy, airy centers made them a movie-theater staple.","image":"https://upload.wikimedia.org/wikipedia/commons/2/21/Whoppers.jpg"},{"name":"Milk Duds","rarity":"epic","id":"milk-duds","subtitle":"Chocolate","details":"Golden caramel discs sealed in milk chocolate; the 'duds' name came from early batches that missed round.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-11-01_10_25_02_Milk_Duds_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Junior Mints","rarity":"legendary","id":"junior-mints","subtitle":"Chocolate","details":"Created in 1949; a cool, creamy mint center in dark chocolate, long sold as the after-dinner mint in a box.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Junior-Mints-Candy.jpg?width=1024"},{"name":"York Peppermint Pattie","rarity":"legendary","id":"york-peppermint-pattie","subtitle":"Chocolate","details":"Born in York, Pennsylvania in 1940; a sharp peppermint disc enrobed in dark chocolate with a famous snap.","image":"https://upload.wikimedia.org/wikipedia/commons/3/31/Pair_of_York_Peppermint_Patties_%2832726049581%29.jpg"},{"name":"Dove Milk Chocolate Promises","rarity":"epic","id":"dove-milk-chocolate-promises","subtitle":"Chocolate","details":"Individually wrapped milk chocolate squares from Mars, each foil hiding a printed promise message inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dove_Chocolate_%28milk_flavor%2C_white_chocolate%29.jpg?width=1024"},{"name":"Lindt Lindor Milk Chocolate Truffles","rarity":"epic","id":"lindt-lindor-milk-chocolate-truffles","subtitle":"Chocolate","details":"Lindt's signature truffle, created in 1949; a fine milk chocolate shell around an instantly melting center.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lindorkugeln1.jpeg?width=1024"},{"name":"Ferrero Rocher","rarity":"epic","id":"ferrero-rocher","subtitle":"Chocolate","details":"Ferrero's 1982 hazelnut jewel: wafer, chocolate and chopped hazelnuts wrapped in distinctive gold foil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2023_Ferrero_Rocher_%282%29.jpg?width=1024"},{"name":"Ghirardelli Milk Chocolate Squares","rarity":"epic","id":"ghirardelli-milk-chocolate-squares","subtitle":"Chocolate","details":"From San Francisco's Ghirardelli, founded in 1852; individually wrapped milk chocolate squares for sharing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2020-02-23_02_26_30_A_Ghirardelli_Milk_Chocolate_Caramel_Square_broken_into_two_pieces_in_the_Parkway_Village_section_of_Ewing_Township%2C_Mercer_County%2C_New_Jersey.jpg?width=1024"},{"name":"Rolo","rarity":"epic","id":"rolo","subtitle":"Chocolate","details":"Bite-size milk chocolate cups of smooth caramel, packed in a roll; first made by Rowntree in 1937.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rolo-Candies-US.jpg?width=1024"},{"name":"Heath Bar","rarity":"epic","id":"heath-bar","subtitle":"Chocolate","details":"An English-style butter toffee bar in milk chocolate with almond bits, made by the Heath brothers from 1928.","image":"https://images.openfoodfacts.org/images/products/001/070/085/8436/front_en.17.400.jpg"},{"name":"Clark Bar","rarity":"epic","id":"clark-bar","subtitle":"Chocolate","details":"A Pittsburgh classic from 1917; peanut butter crunch and caramel coated in milk chocolate, still curly-topped.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Clark-Bar-Broken.jpg?width=1024"},{"name":"Zagnut","rarity":"uncommon","id":"zagnut","subtitle":"Chocolate","details":"Toasted coconut over a peanut butter core with no chocolate at all; a crunchy old-school bar from 1930.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zagnut-Split.jpg?width=1024"},{"name":"Sixlets","rarity":"uncommon","id":"sixlets","subtitle":"Chocolate","details":"Tiny candy-coated chocolate balls sold by the handful; eight colors make them a baking and party staple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sixlets-Candies.jpg?width=1024"},{"name":"Toffifay","rarity":"uncommon","id":"toffifay","subtitle":"Chocolate","details":"A Storck cup: a whole hazelnut in caramel, topped with chocolate and nougat cream in a golden shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2023_Toffifee_%282%29.jpg?width=1024"},{"name":"Reese's Big Cup","rarity":"epic","id":"reeses-big-cup","subtitle":"Chocolate","details":"The oversized Reese's cup: same peanut butter and milk chocolate, in a thicker, single-serving format.","image":"https://images.openfoodfacts.org/images/products/003/400/043/0956/front_en.138.400.jpg"},{"name":"Reese's Miniatures","rarity":"uncommon","id":"reeses-miniatures","subtitle":"Chocolate","details":"Bite-size peanut butter cups in gold foil, made for candy dishes, baking and handful snacking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Reeses-PB-Cups-Size-Trio.jpg?width=1024"},{"name":"M&M's Peanut Butter","rarity":"uncommon","id":"m-ms-peanut-butter","subtitle":"Chocolate","details":"Peanut butter filling inside a classic candy shell; the creamy, salty-sweet M&M's spin on a cup favorite.","image":"https://images.openfoodfacts.org/images/products/004/000/057/9816/front_en.31.400.jpg"},{"name":"M&M's Caramel","rarity":"uncommon","id":"m-ms-caramel","subtitle":"Chocolate","details":"A soft caramel center in milk chocolate and a crisp shell; a chewy departure from the usual M&M's snap.","image":"https://images.openfoodfacts.org/images/products/004/000/057/9830/front_en.7.400.jpg"},{"name":"Hershey's Milk Chocolate with Almonds","rarity":"uncommon","id":"hersheys-milk-chocolate-with-almonds","subtitle":"Chocolate","details":"Hershey's milk chocolate loaded with almond pieces, adding roast and crunch to the 1900 original bar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-02-07_11_36_37_A_Hershey%27s_Milk_Chocolate_Bar_with_Almonds_with_the_wrapper_still_on_in_the_Franklin_Farm_section_of_Oak_Hill%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"Hershey's Special Dark","rarity":"uncommon","id":"hersheys-special-dark","subtitle":"Chocolate","details":"Hershey's mildly sweet dark chocolate bar; less sugar-forward than milk, with a firmer, deeper cocoa bite.","image":"https://upload.wikimedia.org/wikipedia/commons/8/88/Hershey%27s_Special_Dark_Miniatures.jpg"},{"name":"Krackel","rarity":"uncommon","id":"krackel","subtitle":"Chocolate","details":"Hershey's 1938 answer to Crunch: milk chocolate packed with crisped rice in a break-apart bar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Krackel-Fun-Size.jpg?width=1024"},{"name":"Mr. Goodbar","rarity":"common","id":"mr-goodbar","subtitle":"Chocolate","details":"Hershey's peanut bar from 1925; whole roasted peanuts set in milk chocolate, named for supposedly good pay.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c0/Hershey%27s_Mr_Goodbar_Miniatures.jpg"},{"name":"Skor","rarity":"common","id":"skor","subtitle":"Chocolate","details":"A thin, buttery English toffee bar in milk chocolate, made by Hershey from a Swedish-inspired recipe in 1981.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Skor-Broken.jpg?width=1024"},{"name":"5th Avenue","rarity":"common","id":"5th-avenue","subtitle":"Chocolate","details":"A crunchy peanut butter bar flavored with molasses and coated in chocolate, dating to 1936.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/5th-avenue-broken.jpg?width=1024"},{"name":"Take 5","rarity":"common","id":"take-5","subtitle":"Chocolate","details":"Hershey's five-layer bar from 2004: pretzel, caramel, peanuts, peanut butter and milk chocolate in one bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Take5-Broken.jpg?width=1024"},{"name":"Zero Bar","rarity":"common","id":"zero-bar","subtitle":"Chocolate","details":"From 1920: caramel, peanuts and nougat under a white fudge coating, the pale outlier among chocolate bars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zero-Split.jpg?width=1024"},{"name":"Chunky","rarity":"common","id":"chunky","subtitle":"Chocolate","details":"A thick, chunky square of milk chocolate with peanuts and raisins, sold on its satisfyingly hefty bite.","image":"assets/sets/candy/images/chunky.webp"},{"name":"Caramello","rarity":"common","id":"caramello","subtitle":"Chocolate","details":"Cadbury's pull-apart bar of milk chocolate segments, each hiding a ribbon of smooth golden caramel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caramello.jpg?width=1024"},{"name":"Andes Crème de Menthe Thins","rarity":"common","id":"andes-creme-de-menthe-thins","subtitle":"Chocolate","details":"Three-layer mint thins: dark chocolate around a green creme de menthe center, the classic after-dinner mint.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Andes-Mints.jpg?width=1024"},{"name":"Dove Dark Chocolate Promises","rarity":"common","id":"dove-dark-chocolate-promises","subtitle":"Chocolate","details":"The dark chocolate Promise: a wrapped square with a deeper cocoa flavor and a message tucked in the foil.","image":"assets/sets/candy/images/dove-dark-chocolate-promises.webp"},{"name":"Lindt Lindor White Chocolate Truffles","rarity":"common","id":"lindt-lindor-white-chocolate-truffles","subtitle":"Chocolate","details":"Lindt's white chocolate truffle: a delicate shell around the same melting Lindor center, sweet and creamy.","image":"https://images.openfoodfacts.org/images/products/000/954/201/5978/front_en.5.400.jpg"},{"name":"Lindt Lindor Dark Chocolate Truffles","rarity":"common","id":"lindt-lindor-dark-chocolate-truffles","subtitle":"Chocolate","details":"Lindt's dark truffle, with a bittersweet shell and a smooth, slow-melting dark chocolate filling.","image":"assets/sets/candy/images/lindt-lindor-dark-chocolate-truffles.webp"},{"name":"Ghirardelli Dark Chocolate Sea Salt Caramel Squares","rarity":"common","id":"ghirardelli-dark-chocolate-sea-salt-caramel-squares","subtitle":"Chocolate","details":"Ghirardelli dark chocolate filled with buttery caramel and a hint of sea salt in a wrapped square.","image":"https://images.openfoodfacts.org/images/products/074/759/932/2747/front_fr.12.400.jpg"},{"name":"Ghirardelli Intense Dark 72% Squares","rarity":"common","id":"ghirardelli-intense-dark-72-squares","subtitle":"Chocolate","details":"Ghirardelli's boldest square: intense dark chocolate made with 72 percent cacao, meant for slow savoring.","image":"assets/sets/candy/images/ghirardelli-intense-dark-72-squares.webp"},{"name":"Kinder Bueno","rarity":"common","id":"kinder-bueno","subtitle":"Chocolate","details":"Ferrero's 1990 wafer bar: crisp wafers around hazelnut cream, coated in milk chocolate and chopped nuts.","image":"https://images.openfoodfacts.org/images/products/000/008/005/2760/front_en.719.400.jpg"},{"name":"Kinder Joy","rarity":"common","id":"kinder-joy","subtitle":"Chocolate","details":"Ferrero's split egg: one half chocolate cream with crunchy cocoa balls, the other half a surprise toy.","image":"https://images.openfoodfacts.org/images/products/000/008/031/0891/front_en.134.400.jpg"},{"name":"Kinder Surprise Egg","rarity":"epic","id":"kinder-surprise-egg","subtitle":"Chocolate","details":"Ferrero's worldwide icon from 1974: a foil-wrapped chocolate egg hiding a toy in a yellow capsule inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kinder_Surprise_Egg.jpg?width=1024"},{"name":"Pocky Chocolate","rarity":"epic","id":"pocky-chocolate","subtitle":"Chocolate","details":"Glico's 1966 Japanese classic: a slender biscuit stick dipped in chocolate, made for neat, shareable snacking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pocky-Sticks.jpg?width=1024"},{"name":"Toblerone Milk Chocolate","rarity":"common","id":"toblerone-milk-chocolate","subtitle":"Chocolate","details":"Theodor Tobler's 1908 Swiss bar: triangular milk chocolate peaks with honey and almond nougat throughout.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cc/Toblerone_3362.jpg"},{"name":"Cadbury Dairy Milk Bar","rarity":"common","id":"cadbury-dairy-milk-bar","subtitle":"Chocolate","details":"Cadbury's 1905 bar, made with a glass and a half of milk; famously smooth, creamy British milk chocolate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cadbury-Dairy-Milk-Caramel-Bar.jpg?width=1024"},{"name":"Reese's Sticks","rarity":"common","id":"reeses-sticks","subtitle":"Chocolate","details":"Reese's in stick form: crisp wafers layered with peanut butter and covered in milk chocolate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2020-03-06_07_44_43_Reese%27s_Sticks_in_the_Franklin_Farm_section_of_Oak_Hill%2C_Fairfax_County%2C_Virginia.jpg?width=1024"},{"name":"Reese's Fast Break","rarity":"common","id":"reeses-fast-break","subtitle":"Chocolate","details":"A milk chocolate bar with a peanut butter and soft nougat center, built as Reese's faster, chewier break.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Reeses-Fast-Break-Broken.jpg?width=1024"},{"name":"NutRageous","rarity":"common","id":"nutrageous","subtitle":"Chocolate","details":"Hershey's bar loaded with peanuts, peanut butter and caramel under milk chocolate, an amped-up nut cluster.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NutRageous-Split.jpg?width=1024"},{"name":"Reese's White Creme Cups","rarity":"common","id":"reeses-white-creme-cups","subtitle":"Chocolate","details":"The white creme Reese's cup: peanut butter filling swapped into a sweet white coating instead of milk chocolate.","image":"https://images.openfoodfacts.org/images/products/003/400/000/3341/front_fr.5.400.jpg"},{"name":"M&M's Almond","rarity":"common","id":"m-ms-almond","subtitle":"Chocolate","details":"A whole almond at the center of each piece, under milk chocolate and the trademark colored shell.","image":"https://images.openfoodfacts.org/images/products/004/000/057/9946/front_en.18.400.jpg"},{"name":"M&M's Pretzel","rarity":"common","id":"m-ms-pretzel","subtitle":"Chocolate","details":"A crunchy, salty pretzel ball inside milk chocolate and a shell; sweet-and-salty M&M's from 2010.","image":"https://images.openfoodfacts.org/images/products/004/000/051/3070/front_en.14.400.jpg"},{"name":"M&M's Crispy","rarity":"common","id":"m-ms-crispy","subtitle":"Chocolate","details":"A crisp rice center gives these M&M's a light crunch, lighter in feel than the peanut or plain originals.","image":"assets/sets/candy/images/m-ms-crispy.webp"},{"name":"M&M's Dark Chocolate","rarity":"common","id":"m-ms-dark-chocolate","subtitle":"Chocolate","details":"Plain M&M's in dark chocolate: a less sweet, more cocoa-forward take on the 1941 original lentil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/M%26M%27s_Dark_Chocolate_%283396691643%29.jpg?width=1024"},{"name":"M&M's Fudge Brownie","rarity":"common","id":"m-ms-fudge-brownie","subtitle":"Chocolate","details":"A chewy, brownie-like center in milk chocolate and a shell, inspired by a fresh pan of fudge brownies.","image":"assets/sets/candy/images/m-ms-fudge-brownie.webp"},{"name":"M&M's Minis Milk Chocolate","rarity":"common","id":"m-ms-minis-milk-chocolate","subtitle":"Chocolate","details":"Miniature milk chocolate M&M's, often sold in tubes; the same flavor in a smaller, poppable size.","image":"https://images.openfoodfacts.org/images/products/004/000/058/0164/front_en.21.400.jpg"},{"name":"Snickers Almond","rarity":"common","id":"snickers-almond","subtitle":"Chocolate","details":"Snickers with crunchy almonds in place of peanuts, keeping the caramel and nougat of the 1930 original.","image":"https://images.openfoodfacts.org/images/products/890/243/300/0416/front_en.11.400.jpg"},{"name":"Snickers Peanut Brownie","rarity":"common","id":"snickers-peanut-brownie","subtitle":"Chocolate","details":"Snickers meets a brownie: a chocolate brownie-flavored filling studded with peanuts under milk chocolate.","image":"assets/sets/candy/images/snickers-peanut-brownie.webp"},{"name":"Milky Way Midnight Dark","rarity":"common","id":"milky-way-midnight-dark","subtitle":"Chocolate","details":"The dark chocolate Milky Way: vanilla nougat and caramel under dark chocolate, once sold as Forever Yours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milky-Way-Bars-USUK-Whole.jpg?width=1024"},{"name":"Twix Salted Caramel","rarity":"common","id":"twix-salted-caramel","subtitle":"Chocolate","details":"Twix with salted caramel over the biscuit finger, adding a salty edge to the milk chocolate coating.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Twix_Salted_Caramel_-_25.9.2025.2.jpg?width=1024"},{"name":"Hershey's Symphony Milk Chocolate","rarity":"common","id":"hersheys-symphony-milk-chocolate","subtitle":"Chocolate","details":"Hershey's creamier bar, made with extra milk and cream for a smoother melt than the standard bar.","image":"assets/sets/candy/images/hersheys-symphony-milk-chocolate.webp"},{"name":"Hershey's Hugs","rarity":"common","id":"hersheys-hugs","subtitle":"Chocolate","details":"Hugs are Kisses swirled with white creme stripes around a milk chocolate center, in silver and gold foil.","image":"assets/sets/candy/images/hersheys-hugs.webp"},{"name":"Hershey's Kisses with Almonds","rarity":"common","id":"hersheys-kisses-with-almonds","subtitle":"Chocolate","details":"A classic Kiss with a whole roasted almond hidden at the center of the milk chocolate drop.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5c/Hershey%27s-Kiss-Wrapped-in-Foil-with-Plume-Sticking-Out.jpg"},{"name":"Hershey's Kisses Cookies 'n' Creme","rarity":"common","id":"hersheys-kisses-cookies-n-creme","subtitle":"Chocolate","details":"A white creme Kiss flecked with chocolate cookie bits, matching the Cookies 'n' Creme bar in drop form.","image":"https://upload.wikimedia.org/wikipedia/commons/5/55/Hershey%27s-KISSES-varieties-with-plume-label-and-colored-foil-wrapper.jpg"},{"name":"Hershey's Kisses Special Dark","rarity":"common","id":"hersheys-kisses-special-dark","subtitle":"Chocolate","details":"A mildly sweet dark chocolate Kiss, the Special Dark version of Hershey's 1907 teardrop.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c5/Hershey%27s_KISSES_Chocolate_Flavors_Written_on_Paper_Plume.jpg"},{"name":"Hershey's Nuggets Milk Chocolate","rarity":"common","id":"hersheys-nuggets-milk-chocolate","subtitle":"Chocolate","details":"Extra creamy milk chocolate in a flat, bite-size nugget shape, made for candy bowls and baking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2021-09-04_23_09_08_Several_wrapped_Hershey%27s_Nuggets_%28extra_creamy_milk_chocolate_with_toffee_and_almonds%29_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Reese's Outrageous","rarity":"common","id":"reeses-outrageous","subtitle":"Chocolate","details":"A Reese's cup stuffed with Reese's Pieces and caramel, piling three peanut butter textures into one cup.","image":"assets/sets/candy/images/reeses-outrageous.webp"},{"name":"Whozeewhatzit","rarity":"common","id":"whozeewhatzit","subtitle":"Chocolate","details":"Hershey's layered bar of peanut butter creme and chocolate rice crisps, a playful Whatchamacallit cousin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thingamajig-Split.jpg?width=1024"},{"name":"Raisinets","rarity":"common","id":"raisinets","subtitle":"Chocolate","details":"Chocolate-covered raisins from 1927; plump raisins in milk chocolate, a founding movie-theater candy.","image":"https://upload.wikimedia.org/wikipedia/commons/9/91/Panda_-_Smoothie_Tumma_Suklaarusina.jpg"},{"name":"Goobers","rarity":"common","id":"goobers","subtitle":"Chocolate","details":"Roasted peanuts in milk chocolate, the peanut partner to Raisinets in theater candy counters for decades.","image":"https://upload.wikimedia.org/wikipedia/en/2/2f/Goobers-Wrapper-Small.jpg"},{"name":"Sno-Caps","rarity":"common","id":"sno-caps","subtitle":"Chocolate","details":"Nonpareils for the movies: semisweet chocolate discs covered in tiny white candy sprinkles.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Sno-Caps_Candy_Pile.jpg?width=1024"},{"name":"Buncha Crunch","rarity":"common","id":"buncha-crunch","subtitle":"Chocolate","details":"Bite-size clusters of Crunch bar pieces: crisped rice and milk chocolate in a resealable movie pouch.","image":"https://images.openfoodfacts.org/images/products/009/990/050/6187/front_en.3.400.jpg"},{"name":"Butterfinger Bites","rarity":"common","id":"butterfinger-bites","subtitle":"Chocolate","details":"Butterfinger in poppable form: bite-size pieces of the crisp peanut-butter core in a chocolatey coating.","image":"https://upload.wikimedia.org/wikipedia/en/0/07/Butterfinger-Snackerz-Wrapper-Small.jpg"},{"name":"Kit Kat White Creme","rarity":"common","id":"kit-kat-white-creme","subtitle":"Chocolate","details":"Kit Kat's wafers in a sweet white creme coating, a pale, vanilla-leaning spin on the milk chocolate finger.","image":"https://images.openfoodfacts.org/images/products/000/000/340/5408/front_fr.18.400.jpg"},{"name":"Kit Kat Dark Chocolate","rarity":"common","id":"kit-kat-dark-chocolate","subtitle":"Chocolate","details":"Kit Kat wafers coated in dark chocolate, trading the original's sweetness for a sharper cocoa snap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kit_Kat_Delight_Dark_%28India%2C_2025%29_01.jpg?width=1024"},{"name":"Kit Kat Minis Unwrapped","rarity":"common","id":"kit-kat-minis-unwrapped","subtitle":"Chocolate","details":"Unwrapped miniature Kit Kat wafers in a pouch, skipping the foil for straight-from-the-bag snacking.","image":"https://images.openfoodfacts.org/images/products/003/400/013/9996/front_en.3.400.jpg"},{"name":"Dove Milk Chocolate & Caramel Promises","rarity":"common","id":"dove-milk-chocolate-caramel-promises","subtitle":"Chocolate","details":"A Dove Promise filled with soft caramel, pairing the wrapped square's message with a gooey center.","image":"assets/sets/candy/images/dove-milk-chocolate-caramel-promises.webp"},{"name":"Tony's Chocolonely Milk Chocolate","rarity":"common","id":"tonys-chocolonely-milk-chocolate","subtitle":"Chocolate","details":"A Dutch milk chocolate bar from Tony's Chocolonely, founded in 2005 to push for slave-free chocolate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tony%27s_Chocolonely_01.jpg?width=1024"},{"name":"Godiva Milk Chocolate Bar","rarity":"common","id":"godiva-milk-chocolate-bar","subtitle":"Chocolate","details":"From Brussels chocolatier Godiva, founded in 1926; a smooth, premium milk chocolate bar in gold wrapping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chocolates_Godiva.001_-_Brussel.JPG?width=1024"},{"name":"Whitman's Sampler Assorted Chocolates","rarity":"common","id":"whitmans-sampler-assorted-chocolates","subtitle":"Chocolate","details":"Whitman's Sampler, from 1912: assorted chocolates in a cross-stitch box with a flavor map under the lid.","image":"https://images.openfoodfacts.org/images/products/007/674/010/2359/front_en.3.400.jpg"},{"name":"Russell Stover Assorted Chocolates","rarity":"common","id":"russell-stover-assorted-chocolates","subtitle":"Chocolate","details":"Assorted chocolates from Russell Stover, a boxed-chocolate staple founded in Denver in 1923.","image":"assets/sets/candy/images/russell-stover-assorted-chocolates.webp"},{"name":"Hershey's Zero Sugar Milk Chocolate","rarity":"common","id":"hersheys-zero-sugar-milk-chocolate","subtitle":"Chocolate","details":"Hershey's milk chocolate bar sweetened without sugar, keeping the familiar flavor for sugar-free snacking.","image":"https://images.openfoodfacts.org/images/products/003/400/027/0262/front_en.3.400.jpg"},{"name":"Reese's Zero Sugar Miniature Cups","rarity":"common","id":"reeses-zero-sugar-miniature-cups","subtitle":"Chocolate","details":"Miniature Reese's cups made without sugar, with the same peanut butter filling in a smaller foil cup.","image":"https://images.openfoodfacts.org/images/products/003/400/093/8391/front_en.46.400.jpg"},{"name":"Goo Goo Cluster Original","rarity":"common","id":"goo-goo-cluster-original","subtitle":"Chocolate","details":"Nashville's 1912 Goo Goo Cluster: marshmallow nougat, caramel and peanuts in milk chocolate, a combo pioneer.","image":"assets/sets/candy/images/goo-goo-cluster-original.webp"},{"name":"Idaho Spud","rarity":"common","id":"idaho-spud","subtitle":"Chocolate","details":"An Idaho Candy Co. treat from 1918: cocoa-dusted marshmallow shaped like a potato, with peanut bits.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Idaho-Spud-Split.jpg?width=1024"},{"name":"Cherry Mash","rarity":"common","id":"cherry-mash","subtitle":"Chocolate","details":"A Missouri classic from 1918: cherry fondant covered in crushed peanuts and chocolate, in two round halves.","image":"https://upload.wikimedia.org/wikipedia/commons/8/83/Cherry-Mash-Split.jpg"},{"name":"Mallo Cup","rarity":"common","id":"mallo-cup","subtitle":"Chocolate","details":"Boyer's 1936 cup: milk chocolate around a whipped marshmallow creme center, once packed with play money.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mallo-Cup-Split.jpg?width=1024"},{"name":"Twin Bing","rarity":"common","id":"twin-bing","subtitle":"Chocolate","details":"Sioux City's Twin Bing, from 1923: two cherry nougat peaks covered in chopped peanuts and chocolate.","image":"https://upload.wikimedia.org/wikipedia/commons/6/65/Twinbing.jpg"},{"name":"Nut Goodie","rarity":"common","id":"nut-goodie","subtitle":"Chocolate","details":"Pearson's 1912 cluster: maple-flavored nougat and roasted peanuts coated in milk chocolate, a Minnesota icon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nut-Goodie-Bar.jpg?width=1024"},{"name":"Pearson's Salted Nut Roll","rarity":"common","id":"pearsons-salted-nut-roll","subtitle":"Chocolate","details":"Pearson's 1933 roll: a white nougat center wrapped in caramel and salted peanuts, sweet and salty together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Salted-Nut-Roll-Split.jpg?width=1024"},{"name":"Mountain Bar Cherry","rarity":"common","id":"mountain-bar-cherry","subtitle":"Chocolate","details":"A Washington bar from Brown & Haley: a cherry-flavored mound under chocolate and chopped peanuts.","image":"https://images.openfoodfacts.org/images/products/004/177/040/3295/front_en.3.400.jpg"},{"name":"Rocky Road Original","rarity":"common","id":"rocky-road-original","subtitle":"Chocolate","details":"Annabelle's bar of chocolate, marshmallow and cashews, named for the bumpy road its texture resembles.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5d/Rocky_Road_dessert.jpg"},{"name":"U-No Bar","rarity":"common","id":"u-no-bar","subtitle":"Chocolate","details":"A truffle-like chocolate bar with a light, whipped center, a West Coast old-timer from the Cardinet family.","image":"https://upload.wikimedia.org/wikipedia/en/8/89/U-NO-Wrapper-Small.jpg"},{"name":"Hershey's Drops Milk Chocolate","rarity":"common","id":"hersheys-drops-milk-chocolate","subtitle":"Chocolate","details":"Unwrapped, candy-coated discs of Hershey's milk chocolate, made to pour straight from the pouch.","image":"assets/sets/candy/images/hersheys-drops-milk-chocolate.webp"},{"name":"Reese's Cup Thins","rarity":"common","id":"reeses-cup-thins","subtitle":"Chocolate","details":"A slimmer Reese's cup with the same peanut butter and milk chocolate, in a thinner, crisper ratio.","image":"https://images.openfoodfacts.org/images/products/003/400/046/0649/front_en.11.400.jpg"},{"name":"Hershey's Kisses Cherry Cordial","rarity":"common","id":"hersheys-kisses-cherry-cordial","subtitle":"Chocolate","details":"A seasonal Kiss with a cherry cordial filling, bringing the boxed-cherry flavor to Hershey's drop shape.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9b/Hershey%27s_Kisses_and_Cherry_Cordial_Creme_Kisses.jpg"},{"name":"Ghirardelli Milk Chocolate Caramel Squares","rarity":"common","id":"ghirardelli-milk-chocolate-caramel-squares","subtitle":"Chocolate","details":"Ghirardelli milk chocolate squares with a soft, flowing caramel center, individually wrapped for sharing.","image":"https://images.openfoodfacts.org/images/products/074/759/941/1137/front_fr.4.400.jpg"},{"name":"Lindt Lindor Caramel Milk Chocolate Truffles","rarity":"common","id":"lindt-lindor-caramel-milk-chocolate-truffles","subtitle":"Chocolate","details":"A Lindor truffle with caramel blended into the milk chocolate center, for an extra buttery melt.","image":"assets/sets/candy/images/lindt-lindor-caramel-milk-chocolate-truffles.webp"},{"name":"Haribo Goldbears","rarity":"chase","id":"haribo-goldbears","subtitle":"Gummies & Jellies","details":"Haribo's original gummi bears, created in Germany in 1922 by Hans Riegel of Bonn; the bear that started it all.","image":"https://images.openfoodfacts.org/images/products/869/121/609/0439/front_fr.20.400.jpg"},{"name":"Jelly Belly Assorted Jelly Beans","rarity":"chase","id":"jelly-belly-assorted-jelly-beans","subtitle":"Gummies & Jellies","details":"Jelly beans with true-to-name flavors, launched in California in 1976 in eight original tastes like root beer.","image":"https://images.openfoodfacts.org/images/products/007/156/798/8223/front_en.9.400.jpg"},{"name":"Nerds Gummy Clusters Rainbow","rarity":"legendary","id":"nerds-gummy-clusters-rainbow","subtitle":"Gummies & Jellies","details":"A gummy center coated in crunchy, tangy Nerds candy; sweet, tart and chewy in a single rainbow bite.","image":"https://images.openfoodfacts.org/images/products/007/920/005/5233/front_en.32.400.jpg"},{"name":"Swedish Fish","rarity":"epic","id":"swedish-fish","subtitle":"Gummies & Jellies","details":"Red fish-shaped winegums from Sweden's Malaco in the 1950s, made for American tastes; chewy, not gelatin-soft.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ed/Swedishfish.jpg"},{"name":"Black Forest Gummy Bears","rarity":"epic","id":"black-forest-gummy-bears","subtitle":"Gummies & Jellies","details":"Fruit-juice gummy bears from the Black Forest brand, known for a soft bite and bright, juicy fruit flavors.","image":"assets/sets/candy/images/black-forest-gummy-bears.webp"},{"name":"Albanese 12 Flavor Gummi Bears","rarity":"rare","id":"albanese-12-flavor-gummi-bears","subtitle":"Gummies & Jellies","details":"Indiana-made gummi bears in 12 flavors, prized for a notably soft, fresh texture and a white grape base.","image":"https://upload.wikimedia.org/wikipedia/commons/6/66/Gummy_bears.jpg"},{"name":"Life Savers Gummies Five Flavors","rarity":"epic","id":"life-savers-gummies-five-flavors","subtitle":"Gummies & Jellies","details":"Ring-shaped gummies in five fruit flavors, the chewy spinoff of the classic Life Savers roll.","image":"assets/sets/candy/images/life-savers-gummies-five-flavors.webp"},{"name":"Welch's Mixed Fruit Fruit Snacks","rarity":"epic","id":"welchs-mixed-fruit-fruit-snacks","subtitle":"Gummies & Jellies","details":"Welch's fruit snacks made with real fruit as the first ingredient, in a mixed fruit pouch for lunchboxes.","image":"https://images.openfoodfacts.org/images/products/003/485/622/6987/front_fr.3.400.jpg"},{"name":"Gushers Strawberry Splash","rarity":"legendary","id":"gushers-strawberry-splash","subtitle":"Gummies & Jellies","details":"Betty Crocker's 1991 fruit snack with a liquid juice center that bursts when you bite the gummy shell.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f7/Betty_Crocker_Fruit_Gushers_pieces_%28cropped%29.jpg"},{"name":"Fruit by the Foot Strawberry","rarity":"legendary","id":"fruit-by-the-foot-strawberry","subtitle":"Gummies & Jellies","details":"A three-foot roll of strawberry fruit snack from 1991, unrolled and peeled for a snack that doubles as play.","image":"https://images.openfoodfacts.org/images/products/001/600/019/4304/front_en.38.400.jpg"},{"name":"Fruit Roll-Ups Strawberry Sensation","rarity":"epic","id":"fruit-roll-ups-strawberry-sensation","subtitle":"Gummies & Jellies","details":"General Mills' rolled fruit snack from 1983; a flat strawberry sheet you unroll, peel and eat by hand.","image":"https://images.openfoodfacts.org/images/products/001/600/035/5408/front_en.31.400.jpg"},{"name":"Haribo Happy Cola","rarity":"rare","id":"haribo-happy-cola","subtitle":"Gummies & Jellies","details":"Haribo's cola-bottle gummies, flavored like cola with a fizzy tang, shaped as tiny soda bottles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Huge_Haribo_Cola_%285357983003%29.jpg?width=1024"},{"name":"Haribo Twin Snakes","rarity":"rare","id":"haribo-twin-snakes","subtitle":"Gummies & Jellies","details":"Haribo's joined pair: one sweet snake and one sour snake twisted together in a single two-flavor gummy.","image":"https://images.openfoodfacts.org/images/products/004/223/834/0954/front_en.7.400.jpg"},{"name":"Mike and Ike Original Fruits","rarity":"epic","id":"mike-and-ike-original-fruits","subtitle":"Gummies & Jellies","details":"Just Born's oblong fruit chews from 1940, named for two employees; chewy, juicy and sugar-dusted-free.","image":"https://upload.wikimedia.org/wikipedia/en/8/87/New_Mike_and_Ike_Original_Fruits_packaging_launched_in_2013.png"},{"name":"Hot Tamales Fierce Cinnamon","rarity":"epic","id":"hot-tamales-fierce-cinnamon","subtitle":"Gummies & Jellies","details":"Just Born's fierce cinnamon chews from 1950, using the Mike and Ike shape for a hot, spicy bite.","image":"https://images.openfoodfacts.org/images/products/007/097/047/4620/front_en.11.400.jpg"},{"name":"Dots Original Gum Drops","rarity":"rare","id":"dots-original-gum-drops","subtitle":"Gummies & Jellies","details":"Gum drops in a theater box since 1945; sugar-crusted jellies in spice and fruit flavors, minus any gum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gumdrops_laying_on_table.jpg?width=1024"},{"name":"Jujyfruits","rarity":"rare","id":"jujyfruits","subtitle":"Gummies & Jellies","details":"Chewy fruit-shaped jellies from 1920, a theater classic in shapes like bananas, pineapples and bunches of grapes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ferrara-Candy-Jujyfruits.jpg?width=1024"},{"name":"Jujubes","rarity":"rare","id":"jujubes","subtitle":"Gummies & Jellies","details":"The firmer cousin of Jujyfruits: small, dense gum drops with a longer chew and old-fashioned flavors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ferrara-Candy-Jujubes.jpg?width=1024"},{"name":"Starburst Gummies Original","rarity":"rare","id":"starburst-gummies-original","subtitle":"Gummies & Jellies","details":"Starburst flavors in gummy form: soft, juicy squares of strawberry, cherry, orange and lemon without the chew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starburst_Gummies.jpg?width=1024"},{"name":"Skittles Gummies Original","rarity":"rare","id":"skittles-gummies-original","subtitle":"Gummies & Jellies","details":"Original Skittles fruit flavors as soft gummies, trading the hard shell for a tender, juicy bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skittles_Gummies.jpg?width=1024"},{"name":"Nerds Gummy Clusters Very Berry","rarity":"rare","id":"nerds-gummy-clusters-very-berry","subtitle":"Gummies & Jellies","details":"The Very Berry Gummy Clusters: a chewy gummy core under a crunchy coat of berry-flavored Nerds.","image":"https://images.openfoodfacts.org/images/products/007/920/008/2277/front_en.6.400.jpg"},{"name":"Haribo Watermelon","rarity":"uncommon","id":"haribo-watermelon","subtitle":"Gummies & Jellies","details":"Haribo gummies shaped and flavored like watermelon slices, with a soft foam layer under the fruit top.","image":"https://images.openfoodfacts.org/images/products/004/223/872/3320/front_fr.10.400.jpg"},{"name":"Haribo Peaches","rarity":"uncommon","id":"haribo-peaches","subtitle":"Gummies & Jellies","details":"Sugar-dusted peach gummies from Haribo, soft and juicy with a ripe peach flavor and a tender bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Haribo_Pfirsiche-2552.jpg?width=1024"},{"name":"Haribo Starmix","rarity":"uncommon","id":"haribo-starmix","subtitle":"Gummies & Jellies","details":"Haribo's mix bag of favorites: gummy rings, eggs, cola bottles and bears gathered in one assortment.","image":"assets/sets/candy/images/haribo-starmix.webp"},{"name":"Black Forest Gummy Worms","rarity":"uncommon","id":"black-forest-gummy-worms","subtitle":"Gummies & Jellies","details":"Black Forest gummy worms in paired fruit flavors, soft and stretchy with a juicy, fruit-forward taste.","image":"assets/sets/candy/images/black-forest-gummy-worms.webp"},{"name":"Black Forest Juicy Burst Fruit Snacks","rarity":"uncommon","id":"black-forest-juicy-burst-fruit-snacks","subtitle":"Gummies & Jellies","details":"Black Forest fruit snacks with a liquid-filled center, designed to burst with juice at first bite.","image":"assets/sets/candy/images/black-forest-juicy-burst-fruit-snacks.webp"},{"name":"Welch's Berries 'n Cherries Fruit Snacks","rarity":"uncommon","id":"welchs-berries-n-cherries-fruit-snacks","subtitle":"Gummies & Jellies","details":"Welch's fruit snacks in berry and cherry flavors, made with real fruit for a deeper, darker fruit mix.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Welch%27s_Fruit_Snacks_%284239096810%29.jpg?width=1024"},{"name":"Mott's Assorted Fruit Fruit Snacks","rarity":"uncommon","id":"motts-assorted-fruit-fruit-snacks","subtitle":"Gummies & Jellies","details":"Mott's fruit-shaped snacks made with fruit and vegetable juices, a lunchbox regular in assorted fruit.","image":"assets/sets/candy/images/motts-assorted-fruit-fruit-snacks.webp"},{"name":"Betty Crocker Scooby-Doo! Fruit Snacks","rarity":"uncommon","id":"betty-crocker-scooby-doo-fruit-snacks","subtitle":"Gummies & Jellies","details":"Betty Crocker fruit snacks shaped like Scooby-Doo and the Mystery Inc. gang, in mixed fruit flavors.","image":"assets/sets/candy/images/betty-crocker-scooby-doo-fruit-snacks.webp"},{"name":"Gushers Tropical Flavors","rarity":"uncommon","id":"gushers-tropical-flavors","subtitle":"Gummies & Jellies","details":"Gushers in tropical flavors like pineapple and tropical punch, each piece hiding a splash of juice.","image":"assets/sets/candy/images/gushers-tropical-flavors.webp"},{"name":"Fruit by the Foot Berry Tie-Dye","rarity":"uncommon","id":"fruit-by-the-foot-berry-tie-dye","subtitle":"Gummies & Jellies","details":"Fruit by the Foot in a swirled berry tie-dye flavor, unrolling in a rainbow-striped three-foot strip.","image":"https://images.openfoodfacts.org/images/products/001/600/027/7007/front_en.21.400.jpg"},{"name":"Fruit Roll-Ups Tropical Tie-Dye","rarity":"uncommon","id":"fruit-roll-ups-tropical-tie-dye","subtitle":"Gummies & Jellies","details":"Fruit Roll-Ups in tropical tie-dye: a marbled, multicolor sheet with mixed tropical fruit flavors.","image":"https://images.openfoodfacts.org/images/products/001/600/039/7002/front_en.11.400.jpg"},{"name":"Jelly Belly Very Cherry Jelly Beans","rarity":"uncommon","id":"jelly-belly-very-cherry-jelly-beans","subtitle":"Gummies & Jellies","details":"Jelly Belly's best-loved flavor: a very cherry bean with a true cherry taste from shell to center.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jelly_Belly.png?width=320"},{"name":"Jelly Belly Buttered Popcorn Jelly Beans","rarity":"uncommon","id":"jelly-belly-buttered-popcorn-jelly-beans","subtitle":"Gummies & Jellies","details":"The love-it-or-hate-it Jelly Belly: a bean that tastes like hot buttered popcorn, carnival stand and all.","image":"assets/sets/candy/images/jelly-belly-buttered-popcorn-jelly-beans.webp"},{"name":"Jelly Belly Juicy Pear Jelly Beans","rarity":"uncommon","id":"jelly-belly-juicy-pear-jelly-beans","subtitle":"Gummies & Jellies","details":"A juicy pear bean with a speckled green shell, capturing ripe pear flavor in Jelly Belly's true-to-name style.","image":"https://images.openfoodfacts.org/images/products/007/157/001/0072/front_en.6.400.jpg"},{"name":"Jelly Belly Cotton Candy Jelly Beans","rarity":"uncommon","id":"jelly-belly-cotton-candy-jelly-beans","subtitle":"Gummies & Jellies","details":"A pastel pink Jelly Belly that tastes like spun sugar at the fair, cotton candy in jelly bean form.","image":"https://images.openfoodfacts.org/images/products/007/156/798/1941/front_fr.12.400.jpg"},{"name":"Mike and Ike Mega Mix","rarity":"uncommon","id":"mike-and-ike-mega-mix","subtitle":"Gummies & Jellies","details":"Mike and Ike Mega Mix: ten fruit flavors in one box, including sour-adjacent twists on the 1940 chew.","image":"https://images.openfoodfacts.org/images/products/007/097/047/5368/front_en.23.400.jpg"},{"name":"Mike and Ike Berry Blast","rarity":"uncommon","id":"mike-and-ike-berry-blast","subtitle":"Gummies & Jellies","details":"Mike and Ike in berry mode: raspberry, blueberry and strawberry chews in the classic oblong shape.","image":"https://images.openfoodfacts.org/images/products/007/097/047/5344/front_en.3.400.jpg"},{"name":"Mike and Ike Tropical Typhoon","rarity":"uncommon","id":"mike-and-ike-tropical-typhoon","subtitle":"Gummies & Jellies","details":"Mike and Ike Tropical Typhoon: island flavors like mango and pineapple in the soft, juicy chew.","image":"assets/sets/candy/images/mike-and-ike-tropical-typhoon.webp"},{"name":"Mike and Ike Red Rageous","rarity":"common","id":"mike-and-ike-red-rageous","subtitle":"Gummies & Jellies","details":"Mike and Ike Red Rageous: an all-red box mixing cherry, strawberry, watermelon and fruit punch chews.","image":"assets/sets/candy/images/mike-and-ike-red-rageous.webp"},{"name":"Brach's Spice Drops","rarity":"common","id":"brachs-spice-drops","subtitle":"Gummies & Jellies","details":"Brach's sugar-crusted gum drops flavored with warm spices like cinnamon, clove and spearmint.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fruit_flavoured_gumdrops.JPG?width=1024"},{"name":"Chuckles Original Jelly Candies","rarity":"common","id":"chuckles-original-jelly-candies","subtitle":"Gummies & Jellies","details":"Sugar-coated jelly bars from 1921 in five flavors, including licorice, sold as a segmented candy stick.","image":"https://upload.wikimedia.org/wikipedia/en/7/79/Chuckles-Wrapper-Small.jpg"},{"name":"Brach's Orange Slices","rarity":"common","id":"brachs-orange-slices","subtitle":"Gummies & Jellies","details":"Brach's jelly candy in orange wedge shapes, rolled in sugar to mimic a fresh citrus slice.","image":"assets/sets/candy/images/brachs-orange-slices.webp"},{"name":"Sunkist Fruit Gems","rarity":"common","id":"sunkist-fruit-gems","subtitle":"Gummies & Jellies","details":"Soft pectin fruit jellies in natural flavors, individually wrapped; tender, not gummy, with a clean fruit taste.","image":"https://upload.wikimedia.org/wikipedia/en/1/1f/Sunkist_1680.jpg"},{"name":"Starburst Jellybeans Original","rarity":"common","id":"starburst-jellybeans-original","subtitle":"Gummies & Jellies","details":"Starburst flavors as jellybeans: soft-centered beans in strawberry, cherry, orange and lemon for spring bags.","image":"assets/sets/candy/images/starburst-jellybeans-original.webp"},{"name":"Jolly Rancher Gummies Original","rarity":"common","id":"jolly-rancher-gummies-original","subtitle":"Gummies & Jellies","details":"Jolly Rancher's bold fruit flavors in gummy form, keeping the hard candy's intensity in a soft chew.","image":"https://images.openfoodfacts.org/images/products/001/070/085/8412/front_en.8.400.jpg"},{"name":"Life Savers Gummies Collisions","rarity":"common","id":"life-savers-gummies-collisions","subtitle":"Gummies & Jellies","details":"Life Savers gummy rings where two flavors collide in each piece, doubling the fruit in every ring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Life_Savers_Collisions_Gummies.jpg?width=1024"},{"name":"Skittles Gummies Wild Berry","rarity":"common","id":"skittles-gummies-wild-berry","subtitle":"Gummies & Jellies","details":"Skittles Wild Berry flavors as gummies: raspberry, berry punch and strawberry in a soft, shell-free form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skittle_Wild_Berry_Gummies.jpg?width=1024"},{"name":"Haribo Frogs","rarity":"common","id":"haribo-frogs","subtitle":"Gummies & Jellies","details":"Haribo's green frogs with a white foam belly, peach-flavored and shaped for a hop off the candy shelf.","image":"assets/sets/candy/images/haribo-frogs.webp"},{"name":"Haribo Berries","rarity":"common","id":"haribo-berries","subtitle":"Gummies & Jellies","details":"Haribo Berries: raspberry and blackberry gummies with a crunchy beaded coating around a soft center.","image":"assets/sets/candy/images/haribo-berries.webp"},{"name":"Haribo Dinosaurs","rarity":"common","id":"haribo-dinosaurs","subtitle":"Gummies & Jellies","details":"Dinosaur-shaped Haribo gummies in mixed fruit flavors, roaring in T. rex and brontosaurus shapes.","image":"assets/sets/candy/images/haribo-dinosaurs.webp"},{"name":"Haribo Rainbow Worms","rarity":"common","id":"haribo-rainbow-worms","subtitle":"Gummies & Jellies","details":"Haribo's multicolored worms: long, fruity gummy strands twisted in bright rainbow colors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Haribo_Rainbow_Worms_Gummies.jpg?width=1024"},{"name":"Albanese Ultimate 8 Flavor Gummi Bears","rarity":"common","id":"albanese-ultimate-8-flavor-gummi-bears","subtitle":"Gummies & Jellies","details":"Albanese Ultimate bears: eight flavors including exotic picks like Alfonso mango and Amity raspberry.","image":"assets/sets/candy/images/albanese-ultimate-8-flavor-gummi-bears.webp"},{"name":"Welch's Juicefuls Juicy Fruit Snacks","rarity":"common","id":"welchs-juicefuls-juicy-fruit-snacks","subtitle":"Gummies & Jellies","details":"Welch's Juicefuls have a juicy liquid center inside a soft fruit snack, made with real fruit.","image":"https://images.openfoodfacts.org/images/products/003/485/616/2018/front_en.8.400.jpg"},{"name":"Funables Mixed Berry Fruit Snacks","rarity":"common","id":"funables-mixed-berry-fruit-snacks","subtitle":"Gummies & Jellies","details":"Funables mixed berry fruit snacks in fun shapes, made with real fruit juice for lunchbox pouches.","image":"https://images.openfoodfacts.org/images/products/004/142/005/4877/front_en.4.400.jpg"},{"name":"Annie's Organic Summer Strawberry Bunny Fruit Snacks","rarity":"common","id":"annies-organic-summer-strawberry-bunny-fruit-snacks","subtitle":"Gummies & Jellies","details":"Annie's organic fruit snacks in bunny shapes, summer strawberry flavored and made without gelatin.","image":"https://images.openfoodfacts.org/images/products/001/356/211/1077/front_en.15.400.jpg"},{"name":"YumEarth Organic Gummy Bears","rarity":"common","id":"yumearth-organic-gummy-bears","subtitle":"Gummies & Jellies","details":"Organic gummy bears from YumEarth, made with simple ingredients and without the top common allergens.","image":"https://images.openfoodfacts.org/images/products/081/016/501/8945/front_en.3.400.jpg"},{"name":"SmartSweets Sweet Fish","rarity":"common","id":"smartsweets-sweet-fish","subtitle":"Gummies & Jellies","details":"SmartSweets' low-sugar take on red fish candy: sweet, chewy fish sweetened without sugar alcohols.","image":"assets/sets/candy/images/smartsweets-sweet-fish.webp"},{"name":"SpongeBob Krabby Patties Gummy Candy","rarity":"common","id":"spongebob-krabby-patties-gummy-candy","subtitle":"Gummies & Jellies","details":"Gummy Krabby Patties: stackable burger layers of gummy bun, patty and toppings in SpongeBob style.","image":"https://upload.wikimedia.org/wikipedia/commons/1/14/Spongebob_Yummy_Krabby_Patty_unwrapped.jpg"},{"name":"Trolli Dino Rex","rarity":"common","id":"trolli-dino-rex","subtitle":"Gummies & Jellies","details":"Trolli's dinosaur-shaped sour gummies, a short-lived prehistoric spin on the brand's sour lineup.","image":"assets/sets/candy/images/trolli-dino-rex.webp"},{"name":"Brach's Classic Jelly Bird Eggs","rarity":"common","id":"brachs-classic-jelly-bird-eggs","subtitle":"Gummies & Jellies","details":"Brach's speckled jelly bird eggs: classic jellybean flavors in a pastel, egg-shaped Easter form.","image":"https://images.openfoodfacts.org/images/products/004/142/005/1555/front_en.3.400.jpg"},{"name":"Jelly Belly Licorice Jelly Beans","rarity":"common","id":"jelly-belly-licorice-jelly-beans","subtitle":"Gummies & Jellies","details":"A black jelly bean with true licorice flavor, the polarizing pick of the Jelly Belly assortment.","image":"assets/sets/candy/images/jelly-belly-licorice-jelly-beans.webp"},{"name":"Jelly Belly Toasted Marshmallow Jelly Beans","rarity":"common","id":"jelly-belly-toasted-marshmallow-jelly-beans","subtitle":"Gummies & Jellies","details":"Jelly Belly's campfire bean: vanilla marshmallow flavor with a toasted, caramelized edge.","image":"https://images.openfoodfacts.org/images/products/007/157/001/7958/front_en.3.400.jpg"},{"name":"Jelly Belly Dr Pepper Jelly Beans","rarity":"common","id":"jelly-belly-dr-pepper-jelly-beans","subtitle":"Gummies & Jellies","details":"A Jelly Belly bean flavored after Dr Pepper soda, blending its signature mix of fruit and spice notes.","image":"assets/sets/candy/images/jelly-belly-dr-pepper-jelly-beans.webp"},{"name":"Shark Bites Fruit Snacks","rarity":"common","id":"shark-bites-fruit-snacks","subtitle":"Gummies & Jellies","details":"Shark-shaped fruit snacks from General Mills, a 1980s lunchbox favorite with a great white mascot piece.","image":"assets/sets/candy/images/shark-bites-fruit-snacks.webp"},{"name":"Black Forest Organic Gummy Bears","rarity":"common","id":"black-forest-organic-gummy-bears","subtitle":"Gummies & Jellies","details":"Black Forest bears made with organic ingredients, keeping the juicy flavor in a certified organic recipe.","image":"assets/sets/candy/images/black-forest-organic-gummy-bears.webp"},{"name":"Albanese Gummi Worms","rarity":"common","id":"albanese-gummi-worms","subtitle":"Gummies & Jellies","details":"Albanese's two-flavor gummi worms, long and soft with the brand's signature fresh, juicy bite.","image":"assets/sets/candy/images/albanese-gummi-worms.webp"},{"name":"Mott's Medleys Assorted Fruit Snacks","rarity":"common","id":"motts-medleys-assorted-fruit-snacks","subtitle":"Gummies & Jellies","details":"Mott's Medleys pair fruit and veggie juices in assorted shapes, a blend beyond the standard fruit pouch.","image":"https://images.openfoodfacts.org/images/products/075/202/561/9353/front_en.3.400.jpg"},{"name":"Fruit Roll-Ups Jolly Rancher Watermelon","rarity":"common","id":"fruit-roll-ups-jolly-rancher-watermelon","subtitle":"Gummies & Jellies","details":"A Fruit Roll-Ups sheet flavored like Jolly Rancher watermelon, mashup of two bold fruit brands.","image":"assets/sets/candy/images/fruit-roll-ups-jolly-rancher-watermelon.webp"},{"name":"Trolli Peachie O's","rarity":"common","id":"trolli-peachie-os","subtitle":"Gummies & Jellies","details":"Trolli's peach rings: soft gummy O's with ripe peach flavor and a tangy, sugar-sour coating.","image":"assets/sets/candy/images/trolli-peachie-os.webp"},{"name":"Skittles Original Fruit Chews","rarity":"chase","id":"skittles-original-fruit-chews","subtitle":"Chewy, Taffy & Licorice","details":"Mars's rainbow fruit chews, launched in Britain in 1974: a crisp candy shell over a chewy center in five original fruit flavors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Skittles-Louisiana-2003.jpg?width=800"},{"name":"Starburst Original Fruit Chews","rarity":"chase","id":"starburst-original-fruit-chews","subtitle":"Chewy, Taffy & Licorice","details":"Debuted in Britain in 1960 as Opal Fruits and renamed Starburst for the US in 1967; Mars's juicy squares come individually wrapped.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starburst-Candies.jpg?width=1024"},{"name":"Twizzlers Strawberry Twists","rarity":"legendary","id":"twizzlers-strawberry-twists","subtitle":"Chewy, Taffy & Licorice","details":"Hershey's strawberry licorice-style twists, the flagship flavor of a brand dating to 1929, and a movie-theater concession staple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2019-11-16_00_55_13_A_packet_of_Strawberry_Twizzlers_Twists_in_the_Dulles_section_of_Sterling%2C_Loudoun_County%2C_Virginia.jpg?width=1024"},{"name":"Tootsie Roll","rarity":"epic","id":"tootsie-roll","subtitle":"Chewy, Taffy & Licorice","details":"Created in 1896 by Leo Hirshfield in New York; the chewy chocolate-caramel roll was named after his daughter's nickname, Tootsie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tootsie-Roll-WU.jpg?width=1024"},{"name":"Laffy Taffy Cherry","rarity":"epic","id":"laffy-taffy-cherry","subtitle":"Chewy, Taffy & Licorice","details":"Wonka's cherry taffy bar, stretchy and slow to chew, with a printed joke on every wrapper in the Laffy Taffy tradition.","image":"https://upload.wikimedia.org/wikipedia/en/b/bb/Laffy-Taffy-Wrapper-Small.jpg"},{"name":"Airheads Cherry","rarity":"epic","id":"airheads-cherry","subtitle":"Chewy, Taffy & Licorice","details":"Perfetti Van Melle launched Airheads in 1985; the flat cherry taffy bar is molded into balloon shapes before eating.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Airheads_candy_flavors.jpg?width=1024"},{"name":"Red Vines Original Red Twists","rarity":"epic","id":"red-vines-original-red-twists","subtitle":"Chewy, Taffy & Licorice","details":"American Licorice Company's soft red twists, flavored with red berry notes rather than licorice root, and sold in ropes and bites.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ea/Red_Vines_%281808642975%29.jpg"},{"name":"PayDay Peanut Caramel Bar","rarity":"epic","id":"payday-peanut-caramel-bar","subtitle":"Chewy, Taffy & Licorice","details":"Introduced in 1932 by the Hollywood Candy Company; salted peanuts rolled in caramel, famously with no chocolate coating at all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-PayDay-Broken.jpg?width=1024"},{"name":"Werther's Original Chewy Caramels","rarity":"epic","id":"werthers-original-chewy-caramels","subtitle":"Chewy, Taffy & Licorice","details":"Storck's chewy take on its butter-and-cream hard caramel, softening the Werther's Original flavor into a bite-size wrapped chew.","image":"https://upload.wikimedia.org/wikipedia/commons/0/03/2021-07-08_09_37_06_An_individual_Werther%27s_Original_Soft_Caramel_candy_in_the_Franklin_Farm_section_of_Oak_Hill%2C_Fairfax_County%2C_Virginia.jpg"},{"name":"Kraft Caramels","rarity":"rare","id":"kraft-caramels","subtitle":"Chewy, Taffy & Licorice","details":"Kraft's individually wrapped caramel cubes, a lunchbox sweet that doubles as the home baker's shortcut for sauces and apples.","image":"https://images.openfoodfacts.org/images/products/000/000/703/0000/front_en.8.400.jpg"},{"name":"Sugar Babies","rarity":"rare","id":"sugar-babies","subtitle":"Chewy, Taffy & Licorice","details":"Launched in 1935, these milk-caramel drops are the bite-size sibling of the Sugar Daddy pop, made for slow, sticky chewing.","image":"assets/sets/candy/images/sugar-babies.webp"},{"name":"Charleston Chew Vanilla","rarity":"rare","id":"charleston-chew-vanilla","subtitle":"Chewy, Taffy & Licorice","details":"Nougat taffy in vanilla, named for the Charleston dance craze; fans freeze it so the long bar shatters into bite-size shards.","image":"https://upload.wikimedia.org/wikipedia/en/2/2e/Charleston-Chew-Vanilla-Wrapper-Small.jpg"},{"name":"Bit-O-Honey","rarity":"rare","id":"bit-o-honey","subtitle":"Chewy, Taffy & Licorice","details":"Debuted in 1924, this honey-flavored almond taffy is stretched into thin bars, giving a chew that outlasts most penny candies.","image":"https://upload.wikimedia.org/wikipedia/commons/1/12/BOH_ind_wrapped_SINGLE_NEW.jpg"},{"name":"Now and Later Original","rarity":"rare","id":"now-and-later-original","subtitle":"Chewy, Taffy & Licorice","details":"Introduced in 1962 by the Phoenix Candy Company; dense taffy squares so firm the brand promise was 'start now, finish later.'","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Now-and-Laters.jpg?width=1024"},{"name":"Starburst FaveREDs","rarity":"rare","id":"starburst-favereds","subtitle":"Chewy, Taffy & Licorice","details":"A red-only Starburst mix built on strawberry and fruit punch, with cherry and watermelon reds rounding out the pack.","image":"https://images.openfoodfacts.org/images/products/002/200/001/2005/front_en.5.400.jpg"},{"name":"Starburst All Pink","rarity":"rare","id":"starburst-all-pink","subtitle":"Chewy, Taffy & Licorice","details":"An all-strawberry Starburst pack born from fan devotion to the pink chew, graduating from limited run to its own lineup.","image":"assets/sets/candy/images/starburst-all-pink.webp"},{"name":"Skittles Wild Berry","rarity":"epic","id":"skittles-wild-berry","subtitle":"Chewy, Taffy & Licorice","details":"Skittles' berry spin-off: raspberry, wild cherry, strawberry, berry punch and melon berry under the same crunchy shell.","image":"assets/sets/candy/images/skittles-wild-berry.webp"},{"name":"Skittles Tropical","rarity":"rare","id":"skittles-tropical","subtitle":"Chewy, Taffy & Licorice","details":"Skittles in tropical dress: banana berry, kiwi lime, mango tangelo, pineapple passionfruit and strawberry star fruit.","image":"assets/sets/candy/images/skittles-tropical.webp"},{"name":"Good & Plenty","rarity":"epic","id":"good-plenty","subtitle":"Chewy, Taffy & Licorice","details":"Introduced in 1893, America's oldest branded candy: licorice pellets in a pink-and-white candy shell, still in its vintage box.","image":"https://upload.wikimedia.org/wikipedia/commons/8/82/Good_%26_Plenty_licorice_candy.JPG"},{"name":"Twizzlers Pull 'n' Peel Cherry","rarity":"rare","id":"twizzlers-pull-n-peel-cherry","subtitle":"Chewy, Taffy & Licorice","details":"Hershey's cherry Twizzlers made to be pulled apart strand by strand, each licorice-style rope splitting into thin strings.","image":"https://images.openfoodfacts.org/images/products/003/400/054/4431/front_fr.9.400.jpg"},{"name":"Red Vines Black Licorice Twists","rarity":"rare","id":"red-vines-black-licorice-twists","subtitle":"Chewy, Taffy & Licorice","details":"American Licorice Company's black licorice twists, flavored with real licorice character, unlike the red original's berry taste.","image":"assets/sets/candy/images/red-vines-black-licorice-twists.webp"},{"name":"Laffy Taffy Banana","rarity":"uncommon","id":"laffy-taffy-banana","subtitle":"Chewy, Taffy & Licorice","details":"The banana Laffy Taffy bar: pale yellow, intensely banana, joke on the wrapper, and the flavor fans argue about most.","image":"https://images.openfoodfacts.org/images/products/000/000/796/1122/front_en.13.400.jpg"},{"name":"Laffy Taffy Sour Apple","rarity":"uncommon","id":"laffy-taffy-sour-apple","subtitle":"Chewy, Taffy & Licorice","details":"Laffy Taffy's green apple bar trades the line's mellow sweetness for a tart, orchard-sharp chew with the usual wrapper joke.","image":"https://images.openfoodfacts.org/images/products/002/800/077/8965/front_fr.8.400.jpg"},{"name":"Airheads Blue Raspberry","rarity":"uncommon","id":"airheads-blue-raspberry","subtitle":"Chewy, Taffy & Licorice","details":"Airheads' blue raspberry bar, dyed electric blue and stretched thin; the flavor that became the brand's second signature.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Airheads_candy_flavors.jpg?width=1024"},{"name":"Airheads White Mystery","rarity":"uncommon","id":"airheads-white-mystery","subtitle":"Chewy, Taffy & Licorice","details":"The Airheads bar with no declared flavor: the white chew's taste is a rotating secret fans try to guess with every pack.","image":"assets/sets/candy/images/airheads-white-mystery.webp"},{"name":"Hi-Chew Original Mix","rarity":"uncommon","id":"hi-chew-original-mix","subtitle":"Chewy, Taffy & Licorice","details":"Morinaga's Japanese chew, sold since 1975; the original mix packs grape, strawberry and apple in a soft, juicy taffy texture.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hi-Chew.jpg?width=1024"},{"name":"Mamba Original Fruit Chews","rarity":"uncommon","id":"mamba-original-fruit-chews","subtitle":"Chewy, Taffy & Licorice","details":"Storck's German fruit chews, around since 1953, in lemon, strawberry, orange and raspberry, wrapped four sticks to a pack.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ab/Mamba_candies_02.jpg"},{"name":"Riesen Chewy Chocolate Caramel","rarity":"uncommon","id":"riesen-chewy-chocolate-caramel","subtitle":"Chewy, Taffy & Licorice","details":"Storck's Riesen wraps a firm, dark chocolate-flavored caramel in a chocolate coating; the name is German for 'giants.'","image":"https://images.openfoodfacts.org/images/products/007/279/905/7671/front_en.4.400.jpg"},{"name":"Cow Tales Original","rarity":"uncommon","id":"cow-tales-original","subtitle":"Chewy, Taffy & Licorice","details":"Goetze's caramel sticks with a cream center, sold since 1984 and named for the cow, though no milk pail is required to eat one.","image":"https://images.openfoodfacts.org/images/products/007/062/243/1018/front_en.22.400.jpg"},{"name":"Goetze's Caramel Creams","rarity":"uncommon","id":"goetzes-caramel-creams","subtitle":"Chewy, Taffy & Licorice","details":"Goetze's of Baltimore wraps a dollop of cream filling in golden caramel; fans know the bull's-eye cross-section on sight.","image":"https://images.openfoodfacts.org/images/products/007/062/200/0054/front_en.13.400.jpg"},{"name":"Sugar Daddy","rarity":"uncommon","id":"sugar-daddy","subtitle":"Chewy, Taffy & Licorice","details":"A slow-eating caramel lollipop on a stick, dating to the 1920s Welch confectionery line and sibling to Sugar Babies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Candy-Sugar-Daddy-Unwrapped.jpg?width=1024"},{"name":"Mary Jane Peanut Butter Kisses","rarity":"uncommon","id":"mary-jane-peanut-butter-kisses","subtitle":"Chewy, Taffy & Licorice","details":"Created in 1914 and named for the maker's aunt Mary Jane; molasses taffy with a peanut butter smear in the middle.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Candy-Mary-Jane.jpg"},{"name":"Goldenberg's Peanut Chews Original Dark","rarity":"uncommon","id":"goldenbergs-peanut-chews-original-dark","subtitle":"Chewy, Taffy & Licorice","details":"A Philadelphia original from 1917: Goldenberg's packs peanuts and molasses chew under a dark chocolate coating.","image":"https://upload.wikimedia.org/wikipedia/en/c/ce/Peanut-Chews-Dark-Wrapper-Small.jpg"},{"name":"Abba-Zaba Original","rarity":"uncommon","id":"abba-zaba-original","subtitle":"Chewy, Taffy & Licorice","details":"A West Coast taffy bar from 1922 with peanut butter sealed inside white taffy, so the center stays hidden until the bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abba-Zaba_Bar.jpg?width=1024"},{"name":"Chick-O-Stick","rarity":"uncommon","id":"chick-o-stick","subtitle":"Chewy, Taffy & Licorice","details":"Atkinson's crunchy stick of peanut butter and toasted coconut, rolled in red stripes and built to shatter, not bend.","image":"https://upload.wikimedia.org/wikipedia/commons/3/39/Current-chick-o-stick-king-size.jpg"},{"name":"Fralinger's Salt Water Taffy","rarity":"uncommon","id":"fralingers-salt-water-taffy","subtitle":"Chewy, Taffy & Licorice","details":"Atlantic City's boardwalk taffy from Fralinger's, boxing salt water taffy in flavors from molasses to peanut butter since the 1880s.","image":"https://upload.wikimedia.org/wikipedia/commons/6/65/Salt_water_taffy.jpg"},{"name":"Squirrel Nut Zippers","rarity":"uncommon","id":"squirrel-nut-zippers","subtitle":"Chewy, Taffy & Licorice","details":"A retro penny candy: vanilla caramel studded with peanuts, its name borrowed from a Prohibition-era mixed drink.","image":"assets/sets/candy/images/squirrel-nut-zippers.webp"},{"name":"Long Boys Coconut","rarity":"uncommon","id":"long-boys-coconut","subtitle":"Chewy, Taffy & Licorice","details":"Atkinson's Long Boys wrap shredded coconut in soft caramel, rolled into finger-length sticks for a slow tropical chew.","image":"https://images.openfoodfacts.org/images/products/004/116/817/5230/front_en.3.400.jpg"},{"name":"Charleston Chew Chocolate","rarity":"common","id":"charleston-chew-chocolate","subtitle":"Chewy, Taffy & Licorice","details":"Charleston Chew's chocolate nougat bar under a chocolatey coating; freeze it and crack it, per generations of fan advice.","image":"https://upload.wikimedia.org/wikipedia/en/a/a5/Charleston-Chew-Wrapper-Small.jpg"},{"name":"Now and Later Cherry","rarity":"common","id":"now-and-later-cherry","subtitle":"Chewy, Taffy & Licorice","details":"Now and Later's cherry square: the same famously long chew as the original, in a bright red fruit flavor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Now-and-Laters.jpg?width=1024"},{"name":"Tootsie Fruit Chews","rarity":"common","id":"tootsie-fruit-chews","subtitle":"Chewy, Taffy & Licorice","details":"Tootsie Roll's fruit-flavored cousins, chewy squares in cherry, orange, lemon, lime and vanilla instead of cocoa.","image":"https://images.openfoodfacts.org/images/products/007/172/098/8701/front_en.4.400.jpg"},{"name":"Tootsie Frooties Strawberry","rarity":"common","id":"tootsie-frooties-strawberry","subtitle":"Chewy, Taffy & Licorice","details":"Strawberry Frooties are Tootsie's bite-size fruit chews, sold loose in bulk bins and parade handfuls by the dozen.","image":"assets/sets/candy/images/tootsie-frooties-strawberry.webp"},{"name":"Brach's Jelly Nougats","rarity":"common","id":"brachs-jelly-nougats","subtitle":"Chewy, Taffy & Licorice","details":"Brach's nougat studded with tiny fruit jelly pieces, sliced so every bite shows a mosaic of gumdrop colors in white candy.","image":"assets/sets/candy/images/brachs-jelly-nougats.webp"},{"name":"Atkinson's Peanut Butter Bars","rarity":"common","id":"atkinsons-peanut-butter-bars","subtitle":"Chewy, Taffy & Licorice","details":"Atkinson's striped, crunchy peanut butter candy bars, crumbly layers that melt down to a salty-sweet peanut finish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atkinsons-Candy-Co-Peanut-Butter-Bar.jpg?width=1024"},{"name":"Twizzlers Bites Strawberry","rarity":"common","id":"twizzlers-bites-strawberry","subtitle":"Chewy, Taffy & Licorice","details":"Twizzlers in poppable form: bite-size strawberry licorice-style pieces, no tearing or twisting required.","image":"assets/sets/candy/images/twizzlers-bites-strawberry.webp"},{"name":"Good & Fruity","rarity":"common","id":"good-fruity","subtitle":"Chewy, Taffy & Licorice","details":"The discontinued fruity sibling of Good & Plenty: same licorice pellet and hard shell, in bright fruit flavors and colors.","image":"assets/sets/candy/images/good-fruity.webp"},{"name":"Starburst Swirlers","rarity":"common","id":"starburst-swirlers","subtitle":"Chewy, Taffy & Licorice","details":"A discontinued Starburst spin-off: chewy sticks swirling two fruit flavors together in one striped, shareable rope.","image":"assets/sets/candy/images/starburst-swirlers.webp"},{"name":"Sugar Mama","rarity":"common","id":"sugar-mama","subtitle":"Chewy, Taffy & Licorice","details":"The discontinued chocolate-caramel lollipop from the Sugar family, a Sugar Daddy pop dipped in a chocolatey coating.","image":"assets/sets/candy/images/sugar-mama.webp"},{"name":"Hi-Chew Fantasy Mix","rarity":"common","id":"hi-chew-fantasy-mix","subtitle":"Chewy, Taffy & Licorice","details":"Hi-Chew's Fantasy Mix pairs Rainbow Sherbet, Blue Hawaii and Blue Raspberry in Morinaga's soft, extra-juicy chew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hi-Chew.jpg?width=1024"},{"name":"Mamba Sour Fruit Chews","rarity":"common","id":"mamba-sour-fruit-chews","subtitle":"Chewy, Taffy & Licorice","details":"Mamba's sour turn: Storck's fruit chews dusted tart, in lemon, green apple, cherry and raspberry style flavors.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ab/Mamba_candies_02.jpg"}]});
